import numpy as np
from scipy.optimize import least_squares
d=df.copy()
S=d.S.values;I=d.I.values;v=d.v.values
def mk(kind):
    def f(p,S,I):
        Vm=np.exp(p[0]);Km=np.exp(p[1]);Ki=np.exp(p[2])
        if kind=='comp': return Vm*S/(Km*(1+I/Ki)+S)
        if kind=='nonc': return Vm*S/((Km+S)*(1+I/Ki))
        if kind=='unc': return Vm*S/(Km+S*(1+I/Ki))
        if kind=='mixed':
            a=np.exp(p[3]); return Vm*S/(Km*(1+I/Ki)+S*(1+I/(a*Ki)))
    return f
res={}
for k,npar in [('comp',3),('nonc',3),('unc',3),('mixed',4)]:
    f=mk(k);best=None
    for s in range(30):
        p0=np.random.randn(npar)+np.array([2,1,0,0])[:npar]
        try:
            r=least_squares(lambda p:(f(p,S,I)-v),p0)
        except Exception: continue
        if best is None or r.cost<best.cost: best=r
    n=len(v);rss=2*best.cost
    bic=n*np.log(rss/n)+npar*np.log(n)
    res[k]=best
    print(k,np.exp(best.x).round(4),'RSS',round(rss,4),'BIC',round(bic,2))
# no-inhibition baseline
def mm(p):return np.exp(p[0])*S/(np.exp(p[1])+S)
r=least_squares(lambda p:mm(p)-v,[2,0]);rss=2*r.cost
print('MM only',np.exp(r.x).round(3),'BIC',round(48*np.log(rss/48)+2*np.log(48),2))
for I0 in [0,1,3]:
    m=d[d.I==I0]
    print(I0, m.groupby('S').v.apply(list).to_dict())

